// Original agent-authored scientific specimen. Not application source.
#nullable enable
public sealed class LazyCaption
{
    private string? value;
    public int Gets { get; private set; }
    public int Sets { get; private set; }
    public int Allocations { get; private set; }
    public LazyCaption(string? initial) { value = initial; }
    public string? Value
    {
        get { Gets++; return value; }
        set { Sets++; this.value = value; }
    }
    private string Allocate() { Allocations++; return "created"; }
    public string Ensure() => Value ??= Allocate();
}
```
